mapper.select:
select
borrow.*,
student.stu_name,
student.stu_img
from borrow borrow
left join student student on borrow.stu_id = student.id

    and borrow.id = #{id}
    and borrow.stu_id = #{stuId}
    and borrow.name like concat('%',#{name},'%')
    and borrow.img = #{img}
    and borrow.info = #{info}
    and borrow.create_time = #{createTime}
    and borrow.tel = #{tel}
    and student.stu_name like concat('%',#{stuName},'%')
    and student.stu_img = #{stuImg}


    limit #{current},#{pageSize}

select count(*) from borrow borrow
left join student student on borrow.stu_id = student.id

    and borrow.id = #{id}
    and borrow.stu_id = #{stuId}
    and borrow.name like concat('%',#{name},'%')
    and borrow.img = #{img}
    and borrow.info = #{info}
    and borrow.create_time = #{createTime}
    and borrow.tel = #{tel}
    and student.stu_name like concat('%',#{stuName},'%')
    and student.stu_img = #{stuImg}
